import diag as d,json,pathlib,time,threading
class Watch:
 def __init__(self,trace,name,peer=None,hinge=None):
  self.trace=trace;self.name=name;self.peer=peer;self.hinge=hinge;self.rows=[];self.start_offset=trace.stat().st_size;self.offset=self.start_offset;self.stop=threading.Event();self.sent=None;self.error=None
 def __enter__(self):
  self.started=d.now();self.thread=threading.Thread(target=self.loop,daemon=True);self.thread.start();return self
 def loop(self):
  try:
   deadline=time.monotonic()+15
   while not self.stop.is_set() and time.monotonic()<deadline:
    with self.trace.open('rb') as f:f.seek(self.offset);lines=f.readlines();self.offset=f.tell()
    for line in lines:
     row={'host_at':d.now(),'host_epoch':time.time(),'trace':json.loads(line)};self.rows.append(row)
     if self.peer and self.sent is None and row['trace'].get('busy'):
      self.sent={'trigger':row,'ack':self.peer.send('hinge '+str(self.hinge))}
    time.sleep(.01)
  except Exception as exc:self.error=repr(exc)
 def __exit__(self,*args):
  self.stop.set();self.thread.join(timeout=10);assert not self.thread.is_alive();out={'start_offset':self.start_offset,'end_offset':self.offset,'started_at':self.started,'ended_at':d.now(),'sent':self.sent,'error':self.error,'rows':self.rows};(d.P/(self.name+'-watch.json')).write_text(json.dumps(out,indent=2));assert self.error is None,self.error

